var jsonInput = input.get('json');
var pathExpr = input.get('path');
var returnFirst = input.get('returnFirst') === 'true';

if (!jsonInput) {
    output.set('HasErrors', true);
    output.set('ErrorMessage', 'JSON input is required');
    output.set('Result', '');
    tags.trigger('error');
} else if (!pathExpr) {
    output.set('HasErrors', true);
    output.set('ErrorMessage', 'Path is required');
    output.set('Result', '');
    tags.trigger('error');
} else {
    try {
        var data = json.parse(jsonInput);
        var results = [];

        function query(obj, path) {
            if (path === '' || path === '$') {
                results.push(obj);
                return;
            }

            var p = path;
            if (p.charAt(0) === '$') p = p.substring(1);
            if (p.charAt(0) === '.') p = p.substring(1);

            var segments = [];
            var current = '';
            var inBracket = false;

            for (var i = 0; i < p.length; i++) {
                var c = p.charAt(i);
                if (c === '[') {
                    if (current) segments.push({type: 'prop', val: current});
                    current = '';
                    inBracket = true;
                } else if (c === ']') {
                    if (current === '*') {
                        segments.push({type: 'wild'});
                    } else if (!isNaN(parseInt(current))) {
                        segments.push({type: 'idx', val: parseInt(current)});
                    } else {
                        var v = current;
                        if ((v.charAt(0)==='"'||v.charAt(0)==="'") && v.charAt(v.length-1)===v.charAt(0)) {
                            v = v.substring(1, v.length-1);
                        }
                        segments.push({type: 'prop', val: v});
                    }
                    current = '';
                    inBracket = false;
                } else if (c === '.' && !inBracket) {
                    if (current) segments.push({type: 'prop', val: current});
                    current = '';
                    if (p.charAt(i+1) === '.') {
                        segments.push({type: 'recurse'});
                        i++;
                    }
                } else if (c === '*' && !inBracket) {
                    if (current) segments.push({type: 'prop', val: current});
                    segments.push({type: 'wild'});
                    current = '';
                } else {
                    current += c;
                }
            }
            if (current) segments.push({type: 'prop', val: current});

            function traverse(obj, idx) {
                if (idx >= segments.length) {
                    results.push(obj);
                    return;
                }
                if (obj === null || obj === undefined) return;

                var seg = segments[idx];

                if (seg.type === 'prop') {
                    if (typeof obj === 'object' && obj[seg.val] !== undefined) {
                        traverse(obj[seg.val], idx + 1);
                    }
                } else if (seg.type === 'idx') {
                    if (Array.isArray(obj)) {
                        var i = seg.val < 0 ? obj.length + seg.val : seg.val;
                        if (i >= 0 && i < obj.length) {
                            traverse(obj[i], idx + 1);
                        }
                    }
                } else if (seg.type === 'wild') {
                    if (Array.isArray(obj)) {
                        for (var i = 0; i < obj.length; i++) {
                            traverse(obj[i], idx + 1);
                        }
                    } else if (typeof obj === 'object') {
                        var keys = Object.keys(obj);
                        for (var k = 0; k < keys.length; k++) {
                            traverse(obj[keys[k]], idx + 1);
                        }
                    }
                } else if (seg.type === 'recurse') {
                    traverse(obj, idx + 1);
                    if (Array.isArray(obj)) {
                        for (var i = 0; i < obj.length; i++) {
                            traverse(obj[i], idx);
                        }
                    } else if (typeof obj === 'object') {
                        var keys = Object.keys(obj);
                        for (var k = 0; k < keys.length; k++) {
                            traverse(obj[keys[k]], idx);
                        }
                    }
                }
            }

            traverse(obj, 0);
        }

        query(data, pathExpr);

        var resultVal = returnFirst ? (results.length > 0 ? results[0] : null) : results;

        output.set('Result', json.stringify(resultVal));
        output.set('ResultObject', resultVal);
        output.set('MatchCount', results.length);
        output.set('HasMatches', results.length > 0);
        output.set('FirstMatch', results.length > 0 ? json.stringify(results[0]) : '');
        output.set('Path', pathExpr);
        output.set('HasErrors', false);
        output.set('ErrorMessage', '');

        log.info('JSONPath matched ' + results.length + ' result(s)');

        if (results.length > 0) {
            tags.trigger('found');
        } else {
            tags.trigger('not-found');
        }
        tags.trigger('success');

    } catch (ex) {
        log.error('JSONPath failed: ' + ex.message);
        output.set('HasErrors', true);
        output.set('ErrorMessage', ex.message);
        output.set('Result', '');
        tags.trigger('error');
    }
}
